/// Returns the minimum number of inspectors needed to cover `n` items
/// when each inspector covers a contiguous block of length `2*d + 1`.
///
/// Formula: ceil(n / (2*d + 1))
pub fn min_inspectors(n: i8, d: i8) -> i8 {
    // Promote to i32 to avoid any overflow surprises and to simplify arithmetic.
    let n = n as i32;
    let d = d as i32;

    let block = 2 * d + 1;              // max items one inspector can cover
    let result = (n + block - 1) / block; // integer ceil division

    result as i8
}

